const BYTES_IN_MEGABYTE = 1024 * 1024;

export const MAX_UPLOAD_SIZE_BYTES = 20 * BYTES_IN_MEGABYTE;

export const ALLOWED_MIME_TYPES = [
  "application/pdf",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  "image/jpeg",
  "image/png",
] as const;

export const ALLOWED_EXTENSIONS = [
  ".pdf",
  ".docx",
  ".jpg",
  ".jpeg",
  ".png",
] as const;

export const ACCEPT_ATTRIBUTE = [
  ".pdf",
  ".docx",
  ".jpg",
  ".jpeg",
  ".png",
  "application/pdf",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  "image/jpeg",
  "image/png",
].join(",");

function hasAllowedExtension(filename: string): boolean {
  const normalized = filename.trim().toLowerCase();
  return ALLOWED_EXTENSIONS.some((extension) => normalized.endsWith(extension));
}

export function isSupportedUploadFile(file: Pick<File, "name" | "type">): boolean {
  const mimeType = file.type?.trim().toLowerCase();
  return ALLOWED_MIME_TYPES.includes(mimeType as (typeof ALLOWED_MIME_TYPES)[number]) || hasAllowedExtension(file.name);
}

export function validateUploadFile(file: Pick<File, "name" | "size" | "type">): string | null {
  if (!isSupportedUploadFile(file)) {
    return "Formato non supportato. Carica un file PDF, DOCX, JPG o PNG.";
  }

  if (file.size > MAX_UPLOAD_SIZE_BYTES) {
    return "Il file supera il limite di 20 MB.";
  }

  return null;
}

export function formatBytes(bytes: number): string {
  if (bytes < BYTES_IN_MEGABYTE) {
    return `${Math.ceil(bytes / 1024)} KB`;
  }

  return `${(bytes / BYTES_IN_MEGABYTE).toFixed(1)} MB`;
}
