import type { UploadClient, UploadResponse, UploadRuntimeProfile } from "../types";

export class UploadApiError extends Error {
  readonly status: number;
  readonly code: string;

  constructor(status: number, message: string, code = "UPLOAD_FAILED") {
    super(message);
    this.name = "UploadApiError";
    this.status = status;
    this.code = code;
  }
}

interface RuntimeConfig {
  profile: UploadRuntimeProfile;
  apiBaseUrl: string;
}

type EnvShape = Record<string, string | undefined>;

export function resolveUploadRuntimeConfig(env: EnvShape = process.env): RuntimeConfig {
  const profile: UploadRuntimeProfile = env.NEXT_PUBLIC_RUNTIME_PROFILE === "aws" ? "aws" : "local";
  const configuredBaseUrl = env.NEXT_PUBLIC_API_BASE_URL?.trim();

  if (configuredBaseUrl) {
    return {
      profile,
      apiBaseUrl: configuredBaseUrl.replace(/\/+$/, ""),
    };
  }

  if (profile === "local") {
    return {
      profile,
      apiBaseUrl: "http://localhost:8000",
    };
  }

  throw new Error("NEXT_PUBLIC_API_BASE_URL deve essere configurato per il profilo aws.");
}

async function safeJson(response: Response): Promise<unknown> {
  const contentType = response.headers.get("content-type") ?? "";
  if (!contentType.includes("application/json")) {
    return null;
  }

  try {
    return await response.json();
  } catch {
    return null;
  }
}

function extractErrorMessage(payload: unknown, fallback: string): string {
  if (!payload || typeof payload !== "object") {
    return fallback;
  }

  if ("message" in payload && typeof payload.message === "string") {
    return payload.message;
  }

  if (
    "error" in payload &&
    payload.error &&
    typeof payload.error === "object" &&
    "message" in payload.error &&
    typeof payload.error.message === "string"
  ) {
    return payload.error.message;
  }

  return fallback;
}

export function createUploadClient(
  config: RuntimeConfig = resolveUploadRuntimeConfig(),
  fetchImpl: typeof fetch = fetch,
): UploadClient {
  return {
    async upload(file: File): Promise<UploadResponse> {
      const formData = new FormData();
      formData.set("file", file);

      const response = await fetchImpl(`${config.apiBaseUrl}/documents`, {
        method: "POST",
        body: formData,
        headers: {
          "X-Client-Runtime-Profile": config.profile,
        },
      });

      if (!response.ok) {
        const payload = await safeJson(response);
        throw new UploadApiError(
          response.status,
          extractErrorMessage(payload, "Upload non riuscito."),
          `HTTP_${response.status}`,
        );
      }

      const payload = (await response.json()) as Partial<UploadResponse>;

      if (!payload.document_id || !payload.correlation_id) {
        throw new UploadApiError(502, "Risposta upload non valida.", "UPLOAD_INVALID_RESPONSE");
      }

      return {
        document_id: payload.document_id,
        correlation_id: payload.correlation_id,
      };
    },
  };
}
