"use client";

import { useEffect, useMemo, useState } from "react";
import { useMutation } from "@tanstack/react-query";

import { createUploadClient, UploadApiError } from "../api/documents";
import type { AuthState, UploadClient, UploadSuccessState } from "../types";
import { validateUploadFile } from "../validation";

const LOGIN_PATH = "/login?next=/intake/upload";
const UNAUTHORIZED_PATH = "/unauthorized";

export interface UseUploadDocumentOptions {
  authState?: AuthState;
  client?: UploadClient;
  navigate?: (href: string) => void;
  nextActionHrefBuilder?: (documentId: string) => string;
}

function defaultNavigate(href: string): void {
  if (typeof window !== "undefined") {
    window.location.assign(href);
  }
}

export function useUploadDocument(options: UseUploadDocumentOptions = {}) {
  const authState = options.authState ?? "authenticated";
  const client = useMemo(() => options.client ?? createUploadClient(), [options.client]);
  const navigate = options.navigate ?? defaultNavigate;
  const nextActionHrefBuilder = options.nextActionHrefBuilder ?? ((documentId: string) => `/workflow/inbox?highlight=${documentId}`);

  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [validationMessage, setValidationMessage] = useState<string | null>(null);
  const [serverMessage, setServerMessage] = useState<string | null>(null);
  const [success, setSuccess] = useState<UploadSuccessState | null>(null);
  const [redirectTarget, setRedirectTarget] = useState<string | null>(null);

  useEffect(() => {
    if (authState === "unauthenticated") {
      setRedirectTarget(LOGIN_PATH);
      navigate(LOGIN_PATH);
      return;
    }

    if (authState === "forbidden") {
      setRedirectTarget(UNAUTHORIZED_PATH);
      navigate(UNAUTHORIZED_PATH);
    }
  }, [authState, navigate]);

  const mutation = useMutation({
    mutationFn: async (file: File) => client.upload(file),
    onSuccess: (payload) => {
      setServerMessage(null);
      setSuccess({
        ...payload,
        nextActionHref: nextActionHrefBuilder(payload.document_id),
      });
    },
    onError: (error) => {
      setSuccess(null);

      if (error instanceof UploadApiError && (error.status === 401 || error.status === 403)) {
        const target = error.status === 401 ? LOGIN_PATH : UNAUTHORIZED_PATH;
        setRedirectTarget(target);
        navigate(target);
        return;
      }

      setServerMessage(error instanceof Error ? error.message : "Upload non riuscito.");
    },
  });

  function chooseFile(file: File | null): void {
    setSuccess(null);
    setServerMessage(null);

    if (!file) {
      setSelectedFile(null);
      setValidationMessage("Seleziona un file da caricare.");
      return;
    }

    const error = validateUploadFile(file);
    setValidationMessage(error);
    setSelectedFile(error ? null : file);
  }

  async function submit(): Promise<void> {
    if (redirectTarget) {
      return;
    }

    if (!selectedFile) {
      setValidationMessage("Seleziona un file da caricare.");
      return;
    }

    const error = validateUploadFile(selectedFile);
    if (error) {
      setValidationMessage(error);
      return;
    }

    setValidationMessage(null);
    await mutation.mutateAsync(selectedFile);
  }

  return {
    chooseFile,
    submit,
    selectedFile,
    validationMessage,
    serverMessage,
    success,
    redirectTarget,
    isUploading: mutation.isPending,
  };
}

